package com.lcsalvess.bankingsystem.util.actor;

/**
 * Identifier for actors representing operations generated by the system itself,
 * such as daily yield processing.
 *
 * <p>This value is recorded in audit logs instead of a user's name, which is why
 * the corresponding username is reserved.
 */
public final class SystemActor {

  public static final String NAME = "SYSTEM";

  private SystemActor() {
  }
}
